/*
 * A229880  Palindromic prime numbers == 7 (mod 9).
 * https://oeis.org/A229880
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, less
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 12, u32 n <= 12, u64 n <= 1007,
 *            u128 n <= 1007, big any n
 * Helpers:   big_pow, is_prime_big, reverse_decimal
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by searching palindromic primes congruent to 7 modulo 9 */
#include <stdint.h>
#include <stdbool.h>
#include "../utils/big_pow.h"
#include "../utils/reverse_decimal.h"
#include "../utils/is_prime_big.h"

/* Cache of already found terms */
static seq_t *cache = NULL;
static idx_t cached_terms = 0;
static size_t cache_cap   = 0;

/* Palindrome generator state */
static idx_t  gen_len     = 1; /* current length of palindromes */
static idx_t  gen_h       = 1; /* current half value */
static bool   overflowed  = false;
static seq_t  last_pal    = 0;

/* 10^k as uint64_t, for k < 19 */
static uint64_t pow10_u64(unsigned int k)
{
    uint64_t r = 1;
    while (k--) r *= 10ULL;
    return r;
}

/* Ensure cached array has enough space */
static void ensure_cache_cap(idx_t needed)
{
    if (cache_cap < (size_t)needed) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        while (new_cap < (size_t)needed) new_cap <<= 1;
        cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }
}

/* Generate the next palindromic number (in increasing order) */
static seq_t next_pal(void)
{
    seq_t pal;
    size_t halfLen = (gen_len + 1) >> 1;   /* (len+1)/2 */
    idx_t   half = gen_h;
    bool    odd  = (gen_len & 1);
    size_t  exp  = odd ? halfLen - 1 : halfLen;

    /* 10^exp as seq_t */
    seq_t pow10_seq = big_pow((seq_t)10, (seq_t)exp);

    /* reversed half (without the middle digit if odd) */
    seq_t rev = odd ?
        reverse_decimal((seq_t)(half / 10)) :
        reverse_decimal((seq_t)half);

    seq_t half_seq = (seq_t)half;
    pal = half_seq * pow10_seq + rev;

    /* Advance generator state for next call */
    gen_h++;
    size_t limit = pow10_u64(halfLen) - 1;
    if (gen_h > (idx_t)limit) {
        gen_len++;
        gen_h = pow10_u64((gen_len + 1) / 2 - 1);
    }

    /* Detect overflow of seq_t (wrap‑around) */
    if (pal < last_pal) overflowed = true;
    else                 last_pal = pal;
    return pal;
}

/* External function required by the framework */
seq_t a(idx_t n)
{
    if (n < 1) return 0;              /* behaviour for n < 1 is irrelevant */

    /* Generate until we have found n terms */
    while (cached_terms < n && !overflowed) {
        seq_t cand = next_pal();

        if ((cand % 9) != 7) continue;         /* not ≡7 (mod 9) */
        if (!is_prime_big(cand)) continue;      /* not prime */

        ensure_cache_cap(cached_terms + 1);
        cache[cached_terms++] = cand;
    }

    return (n <= cached_terms) ? cache[n - 1] : last_pal;
}
